import {cgpReadFailure} from './gradleOwnedCgpOutcome.js';
/** Evidence checks for diagnostic artifacts; never an approval verifier. */
import {readFile} from 'node:fs/promises';import path from 'node:path';
import {createHash} from 'node:crypto';
import {cgpBudget} from './gradleOwnedCgpBudget.js';
import {cgpCallSummary} from './gradleOwnedCgpRead.js';
const hash=(b:string|Buffer)=>createHash('sha256').update(b).digest('hex');
const check=(v:unknown,reason:string)=>{if(!v)throw Error('cgp_evidence_'+reason);};
export async function cgpSourceReceipt(){const seen=new Map<string,string>(),seeds=['package.json','package-lock.json','tsconfig.json','tsconfig.build.json','vitest.config.ts','src/test/utils/gradleOwnedCgp.test.ts','src/test/utils/gradleOwnedCgpNative.test.ts','src/test/utils/gradleOwnedCgpValidation.test.ts','src/test/fixtures/gradleOwnedCgpProcess.ts','src/test/fixtures/cgp_child.mjs'];async function visit(name:string){name=path.relative(process.cwd(),path.resolve(name)).split(path.sep).join('/');if(seen.has(name))return;check(!name.startsWith('../'),'source_path');const b=await readFile(name);seen.set(name,hash(b));if(!/\.(ts|mjs)$/.test(name))return;const text=b.toString();for(const match of text.matchAll(/(?:from\s*|import\s*\()\s*['"](\.[^'"]+)['"]/g)){let next=path.resolve(path.dirname(name),match[1]!);if(next.endsWith('.js'))next=next.slice(0,-3)+'.ts';await visit(next);}for(const match of text.matchAll(/moduleURL\('([^']+)'\)/g))await visit('src/utils/'+match[1]+'.ts');}
 for(const seed of seeds)await visit(seed);const files=Object.fromEntries([...seen].sort(([a],[b])=>a<b?-1:a>b?1:0));return {files,digest:hash(JSON.stringify(files))};}
export function validateCgpReport(r:any){check(r.schema==='osv-mcp.cgp.measurements.v0','schema');for(const name of ['backendEligible','nativeIsolationVerified','independentRegistryVerified'])check(r[name]===false,'adoption_flag');check(r.originalReadsSkipped===0,'read_skip');check(r.samples.length>0&&r.samples.length<=24,'sample_bound');const groups=new Set(r.samples.map((s:any)=>s.sample));check(r.proxyMs.length===groups.size*6,'sga_proxy_count');check(r.prototypeRuns.length===groups.size,'prototype_count');
 const finite=(n:unknown)=>typeof n==='number'&&Number.isFinite(n)&&n>=0;
 for(const s of r.samples){check(finite(s.elapsedMs)&&finite(s.drainMs),'read_time');check(['completed','deadline-refused','capacity-refused','other-refused'].includes(s.outcome),'read_outcome');check(s.outcome==='completed'?s.reason===null:typeof s.reason==='string'&&cgpReadFailure(s.reason)===s.outcome,'failure_classification');check(s.publishedThisRead===(s.outcome==='completed'?1:0),'publication');check(s.ownerProcesses.length===5&&new Set(s.ownerProcesses.map((o:any)=>o.pid)).size===5,'process_count');check(new Set(s.owners.map((o:any)=>o.role)).size===5&&s.owners.length===5,'owner_count');for(const o of s.owners){check(finite(o.totalCpuMs)&&finite(o.windowMs)&&s.ownerProcesses.some((p:any)=>p.role===o.role&&p.boot===o.boot),'owner_binding');for(const v of Object.values(o.categories) as any[])check(Number.isSafeInteger(v.count)&&v.count>=0&&finite(v.inclusiveWallMs)&&Number.isSafeInteger(v.bytes)&&v.bytes>=0,'category');}for(const p of s.rawSpans)check(s.owners.some((o:any)=>o.role===p.role&&o.boot===p.boot)&&finite(p.startMs)&&finite(p.wallMs)&&finite(p.inclusiveCpuMs),'span');check(JSON.stringify(cgpCallSummary(s.rawSpans,s.readerEvents))===JSON.stringify(s.calls),'call_summary');}
 const comparisons=r.prototypeRuns.map((p:any)=>{const full=p.observations.find((o:any)=>o.mode==='full'),paged=p.observations.find((o:any)=>o.mode==='paged');check(full&&paged&&p.observations.length===2,'trial_modes');check(full.stopped?.reason==='cgp_capacity_exhausted'&&paged.stopped===null,'trial_outcome');check(paged.writes.length===41,'trial_reads');for(const o of [full,paged]){check(finite(o.wallMs)&&Number.isSafeInteger(o.entries)&&o.entries<=8192&&Number.isSafeInteger(o.physicalBytes)&&o.physicalBytes<=512*1024*1024,'trial_capacity');o.writes.forEach((w:any,i:number)=>check(w.revision===i+1&&finite(w.wallMs)&&finite(w.verifyMs)&&w.casBytes+20000<=65536,'trial_write'));}return {sample:p.sample,...cgpBudget(r.samples,r.proxyMs,paged.writes.slice(1),full.writes.slice(1))};});check(JSON.stringify(comparisons)===JSON.stringify(r.budgetComparisons),'budget_comparisons');const worst=[...comparisons].sort((a,b)=>(b.projectedMs??Infinity)-(a.projectedMs??Infinity))[0];check(JSON.stringify(worst)===JSON.stringify(r.budget),'budget');check(r.budget.cg3Gate.startsWith('closed'),'cg3_gate');check(r.executionSources&&hash(JSON.stringify(r.executionSources.files))===r.executionSources.digest,'source_receipt');return {sampleCount:r.samples.length,prototypePairs:r.prototypeRuns.length,go:false};}
